<script setup lang="ts">
import type { PagedResponse } from '~/types/api'; import type { DueReviewItem } from '~/types/domain'; import { formatDateTime } from '~/utils/format'
definePageMeta({ layout: 'app' }); useSeoMeta({ title: 'Review' }); const api = useApi(); const items = ref<DueReviewItem[]>([]); const loading = ref(true); const error = ref<unknown>(); const resourceType = ref('')
async function load() { loading.value = true; error.value = undefined; try { items.value = (await api.get<PagedResponse<DueReviewItem>>('/review-items/due', { resourceType: resourceType.value, page: 1, pageSize: 50 })).items } catch (caught) { error.value = caught } finally { loading.value = false } }
watch(resourceType, load); onMounted(load)
</script>
<template><div><CorePageHeader title="Review" description="Practice what is due, then let the scheduler choose the next interval."><UButton v-if="items.length" to="/app/review/session" icon="i-lucide-play" label="Start review" /></CorePageHeader><div class="toolbar"><select v-model="resourceType"><option value="">All resources</option><option value="KnowledgeNode">Knowledge</option><option value="InterviewQuestion">Interview</option><option value="DsaProblem">DSA</option></select><span>{{ items.length }} due</span></div><CoreLoadingState v-if="loading" label="Loading review queue" /><CoreErrorState v-else-if="error" :error="error" @retry="load" /><CoreEmptyState v-else-if="!items.length" title="You are caught up" description="There are no review items due in this filter." icon="i-lucide-circle-check-big" /><div v-else class="queue"><article v-for="item in items" :key="item.reviewItemId"><div><div class="meta"><CoreStatusBadge :value="item.overdueMinutes > 0 ? 'Overdue' : 'Due'" /><span>{{ item.resourceType }}</span></div><h2>{{ item.resourceTitle }}</h2><p>{{ item.resourcePreview || 'Open the session to practice this item.' }}</p></div><div class="schedule"><strong>{{ item.reviewCount }}</strong><span>reviews</span><small>Due {{ formatDateTime(item.dueAtUtc) }}</small></div></article></div></div></template>
<style scoped>.toolbar { display: flex; align-items: center; justify-content: space-between; margin-bottom: 1rem; }.toolbar select { padding: .5rem .7rem; border: 1px solid var(--ui-border); border-radius: .55rem; }.toolbar span, .meta span, .queue p, .schedule { color: var(--ui-text-muted); }.queue { display: grid; gap: .65rem; }.queue article { display: flex; justify-content: space-between; gap: 1rem; padding: 1rem; border: 1px solid var(--ui-border); border-radius: .75rem; }.meta { display: flex; align-items: center; gap: .5rem; font-size: .75rem; }.queue h2 { margin: .5rem 0 .2rem; font-weight: 700; }.queue p { font-size: .9rem; }.schedule { display: grid; min-width: 8rem; justify-items: end; align-content: center; font-size: .75rem; }.schedule strong { color: var(--ui-text); font-size: 1.25rem; }</style>
